/**
 * Shared AI-content heuristics — titles, channel names, disclosure phrases.
 * Keep in sync with playlist-forge/lib/ai-keywords.js
 */
(function (g) {
  'use strict';

  const KEYWORDS = [
    'ai voice',
    'ai-voiced',
    'ai voiced',
    'ai generated',
    'ai-generated',
    'made with ai',
    'ai narrated',
    'ai narration',
    'generated by ai',
    'text to speech',
    'text-to-speech',
    'elevenlabs',
    'synthetic voice',
    'ai story',
    'ai voiceover',
    'ai voice over',
    'ai cover',
    'ai song',
    'ai slop',
    'ai video',
    'ai videos',
    'ai generated video',
    'chatgpt',
    'gpt-4',
    'suno ai',
    'suno ',
    'udio ai',
    'neural voice',
    'ai news',
    'ai recap',
    'ai documentary',
    'fully ai',
    '100% ai',
    'faceless channel',
    'ai animation',
    'ai animated',
    'veo',
    'sora',
    'kling ai',
    'runway gen',
    'capcut ai',
    'heygen',
    'invideo ai',
    'pictory'
  ];

  const DISCLOSURE_PHRASES = [
    'altered or synthetic content',
    'significantly altered',
    'synthetic content',
    'synthetic media',
    'created with altered',
    'modified or synthetic',
    'generative ai',
    'made with generative',
    'ai-generated content',
    'this video was altered',
    'altered content',
    'sound or visuals were altered',
    'labelled as altered',
    'labeled as altered'
  ];

  const SUMMARY_PHRASES = ['ai-generated', 'ai generated', 'generated by ai', 'ai summary', 'summarized by ai'];

  // Same cache rationale as UNMatch.compileKeyword (see match.js): this is
  // called once per TERM by allHits(), which scoreVideo() calls ~7 times per
  // tile, so an uncached rebuild here costs ~174k RegExp constructions per scan
  // on a long channel feed. match.js is the live path in the extension (both
  // files load as content scripts and this reads g.UNMatch lazily at call time,
  // so it is resolved long after load), but this fallback runs wherever
  // ai-keywords.js is used on its own — the unit tests among them — and it
  // should not have a different performance profile from the real one.
  var LOCAL_KW_CACHE = new Map();
  var LOCAL_KW_CACHE_MAX = 5000;
  function compileKeywordRe(k) {
    const compile = g && g.UNMatch && g.UNMatch.compileKeyword;
    if (compile) return compile(k);
    const raw = String(k == null ? '' : k);
    if (!raw) return null;
    if (LOCAL_KW_CACHE.has(raw)) return LOCAL_KW_CACHE.get(raw);
    const esc = raw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const startsWord = /\w/.test(raw.charAt(0));
    const endsWord = /\w/.test(raw.charAt(raw.length - 1));
    const pat = (startsWord ? '\\b' : '') + esc + (endsWord ? '\\b' : '');
    let re;
    try {
      re = new RegExp(pat, 'i');
    } catch (e) {
      re = null;
    }
    if (LOCAL_KW_CACHE.size >= LOCAL_KW_CACHE_MAX) LOCAL_KW_CACHE.clear();
    LOCAL_KW_CACHE.set(raw, re);
    return re;
  }

  function textHits(text, extraKeywords, useRegex) {
    const original = text || '';
    if (!original.trim()) return null;
    // extraKeywords && extraKeywords.length treated an explicitly empty list
    // ([], "check against nothing") the same as "no list was passed at all"
    // and silently fell back to the full default KEYWORDS — a caller could
    // never actually request "match nothing." Only fall back when
    // extraKeywords itself wasn't provided.
    const kws = extraKeywords != null ? extraKeywords : KEYWORDS;
    if (useRegex) {
      for (const k of kws) {
        try {
          if (new RegExp(k, 'i').test(original)) return k;
        } catch (e) {
          /* skip */
        }
      }
      return null;
    }
    for (let i = 0; i < kws.length; i++) {
      const re = compileKeywordRe(kws[i]);
      if (re && re.test(original)) return kws[i];
    }
    return null;
  }

  function disclosureInText(text) {
    const t = (text || '').toLowerCase();
    if (!t) return false;
    return DISCLOSURE_PHRASES.some((p) => t.includes(p));
  }

  function looksLikeAI(video) {
    if (!video) return false;
    const parts = [video.title, video.channelTitle, video.description]
      .concat(video.tags || [])
      .filter(Boolean);
    for (let i = 0; i < parts.length; i++) {
      if (textHits(parts[i])) return true;
    }
    return disclosureInText(video.description);
  }

  // ---------------------------------------------------------------------------
  // Weighted scoring
  //
  // The original detector was a single flat keyword list where ANY hit meant
  // "this is AI". That produced both reported problems at once:
  //
  //   * False positives — the list contains terms that describe videos ABOUT
  //     AI as readily as videos MADE BY AI. "AI news", "ai video", "chatgpt",
  //     "sora", "veo" all match ordinary commentary, reviews and tutorials. A
  //     tech channel discussing Sora got flagged as AI slop.
  //   * Missed detections — a flat list can't combine weak signals. Three
  //     mild indicators together are far stronger evidence than any one of
  //     them, but a flat list either fires on the first weak term (false
  //     positive) or, if you remove the weak terms to fix that, stops firing
  //     at all (false negative).
  //
  // Signals are now weighted and summed, so strong evidence stands alone and
  // weak evidence has to corroborate. Callers get a 0–100 score plus the
  // reasons, and choose their own threshold.
  //
  // WEIGHTS
  //   100  Conclusive. YouTube's own synthetic-content disclosure — the
  //        uploader literally declared it.
  //    70  Strong. Phrases that only make sense if the video IS AI-generated
  //        ("ai voiceover", "100% ai", "made with ai").
  //    40  Moderate. Named generation tools. Real signal, but reviewers and
  //        news channels say these words too, so one alone is not enough.
  //    20  Weak. Terms that co-occur with AI content but are mostly topical
  //        ("ai news", "chatgpt"). Only meaningful alongside something else.
  //
  // A channel-name hit counts for more than a title hit: a channel CALLED
  // "AI Story Central" is telling you what it produces, whereas a title
  // mentioning AI is often just the subject matter.
  // ---------------------------------------------------------------------------

  const W_DISCLOSURE = 100;
  const W_STRONG = 70;
  const W_TOOL = 40;
  const W_WEAK = 20;

  // Only-if-generated phrasing.
  const STRONG_TERMS = [
    'ai voice', 'ai-voiced', 'ai voiced', 'ai generated', 'ai-generated',
    'made with ai', 'ai narrated', 'ai narration', 'generated by ai',
    'text to speech', 'text-to-speech', 'synthetic voice', 'ai voiceover',
    'ai voice over', 'ai cover', 'ai song', 'ai slop', 'fully ai', '100% ai',
    'ai animation', 'ai animated', 'ai story', 'neural voice', 'faceless channel',
    'ai-generated video', 'entirely ai', 'written by ai', 'narrated by ai'
  ];

  // Named generation tools/services.
  const TOOL_TERMS = [
    'elevenlabs', 'suno ai', 'suno', 'udio ai', 'udio', 'kling ai', 'runway gen',
    'capcut ai', 'heygen', 'invideo ai', 'pictory', 'synthesia', 'midjourney',
    'stable diffusion', 'deepfake', 'd-id', 'fliki'
  ];

  // Topical / ambiguous.
  const WEAK_TERMS = [
    'chatgpt', 'gpt-4', 'gpt-5', 'sora', 'veo', 'ai video', 'ai videos',
    'ai news', 'ai recap', 'ai documentary', 'ai art', 'ai music', 'ai tools'
  ];

  // Phrasing that indicates a HUMAN talking about AI rather than a machine
  // having produced the video: reviews, tutorials, reactions, opinion. These
  // subtract confidence instead of adding it.
  //
  // Without this, naming two tools in a title was enough to cross the
  // threshold — "How I use ChatGPT and Midjourney in my workflow" scored 60
  // and got flagged, which is exactly backwards: a person explaining their
  // workflow is the clearest possible evidence of a human creator.
  const HUMAN_CUES = [
    'how i ', 'how to ', 'my workflow', 'tutorial', 'review', 'reviewing',
    'reaction', 'reacting', 'explained', 'vs ', 'comparison', 'tested',
    'i tried', 'hands on', 'hands-on', 'first look', 'tier list', 'ranked',
    'is it worth', 'beginner', 'guide', 'course', 'lesson', 'podcast',
    'interview', 'behind the scenes', 'my thoughts', 'opinion', 'news',
    'update', 'roundup', 'breakdown', 'analysis', 'documentary about'
  ];
  const HUMAN_PENALTY = 30;

  function anyHit(text, terms) {
    if (!text) return null;
    for (let i = 0; i < terms.length; i++) {
      const re = compileKeywordRe(terms[i]);
      if (re && re.test(text)) return terms[i];
    }
    return null;
  }

  // All distinct terms from one category that appear in the text. Used so
  // repeated evidence of the same kind can accumulate — "AI news and AI tools"
  // really is stronger evidence than "AI news" alone, and stacking weak
  // signals is how borderline slop gets caught without dropping the threshold
  // low enough to start flagging ordinary videos.
  function allHits(text, terms) {
    if (!text) return [];
    const out = [];
    for (let i = 0; i < terms.length; i++) {
      const re = compileKeywordRe(terms[i]);
      if (re && re.test(text)) out.push(terms[i]);
    }
    return out;
  }

  /**
   * Score how likely a video is AI-generated.
   * @returns {{score:number, level:'none'|'low'|'medium'|'high', reasons:string[], matched:string[]}}
   *   score  0–100 (capped)
   *   level  none (<20) | low (20–44) | medium (45–69) | high (>=70)
   */
  function scoreVideo(video) {
    const v = video || {};
    const title = v.title || '';
    const channel = v.channelTitle || v.channel || '';
    const desc = v.description || '';
    const tagText = (v.tags || []).join(' ');

    let score = 0;
    const reasons = [];
    const matched = [];

    // Conclusive: the uploader's own disclosure. Nothing outranks this.
    if (disclosureInText(desc) || v.disclosed === true) {
      return {
        score: W_DISCLOSURE,
        level: 'high',
        reasons: ['Creator disclosed altered or synthetic content'],
        matched: ['disclosure']
      };
    }

    // Additional hits in the same category count for half the previous one
    // (full, then 50%, then 25%…). Repeated evidence should raise confidence,
    // but a title that says "AI" six ways is not six independent proofs — flat
    // stacking would let a single keyword-stuffed title max out the score.
    function add(text, terms, weight, label, bonus) {
      const hits = allHits(text, terms);
      if (!hits.length) return;
      for (let i = 0; i < hits.length; i++) {
        const w = (weight + (i === 0 ? bonus || 0 : 0)) / Math.pow(2, i);
        if (w < 1) break; // no longer meaningful
        score += w;
        matched.push(hits[i]);
        reasons.push(label + ': "' + hits[i] + '"');
      }
    }

    // Channel name carries extra weight — see the note above.
    add(channel, STRONG_TERMS, W_STRONG, 'Channel name', 15);
    add(channel, TOOL_TERMS, W_TOOL, 'Channel name', 10);
    add(title, STRONG_TERMS, W_STRONG, 'Title');
    add(title, TOOL_TERMS, W_TOOL, 'Title');
    add(title, WEAK_TERMS, W_WEAK, 'Title');
    // Description evidence is real but weaker — descriptions are long and
    // often mention tools the creator merely used for one asset.
    add(desc, STRONG_TERMS, Math.round(W_STRONG / 2), 'Description');
    add(tagText, TOOL_TERMS, Math.round(W_TOOL / 2), 'Tag');

    // Human-creator cues pull the score DOWN, but only when the evidence is
    // circumstantial (tools/topical terms). An explicit "AI voiceover" or
    // "made with AI" is the creator describing the video itself, so a word
    // like "review" in the same title must not explain it away — "AI
    // voiceover review of X" is still an AI-voiced video.
    //
    // This used to also veto on anyHit(desc, STRONG_TERMS) — but description
    // evidence is deliberately weighted at HALF strength a few lines up
    // ("descriptions are long and often mention tools the creator merely used
    // for one asset"), precisely because a stray strong-term mention buried
    // in a long description is much weaker evidence than the same term in
    // the title/channel. Letting it veto the human-cue penalty at full
    // strength contradicted that: an ordinary human tutorial whose
    // description happens to mention "ai voiceover" in passing (e.g. "tools
    // other creators use") would suppress the penalty and score too high.
    const strongClaim = !!anyHit(title, STRONG_TERMS) || !!anyHit(channel, STRONG_TERMS);
    if (!strongClaim && score > 0) {
      const cue = anyHit(title, HUMAN_CUES);
      if (cue) {
        score -= HUMAN_PENALTY;
        reasons.push('Human-creator cue: "' + cue.trim() + '" (−' + HUMAN_PENALTY + ')');
      }
    }
    if (score < 0) score = 0;

    // Halving produces fractions; the score is a user-facing percentage.
    score = Math.min(100, Math.round(score));
    const level = score >= 70 ? 'high' : score >= 45 ? 'medium' : score >= 20 ? 'low' : 'none';
    return { score, level, reasons, matched };
  }

  /**
   * Back-compat boolean. `minScore` lets a caller pick its own strictness;
   * the default (45 = "medium") is deliberately above a single WEAK hit, so
   * one topical mention of ChatGPT no longer flags an ordinary video.
   */
  function looksLikeAIScored(video, minScore) {
    const min = typeof minScore === 'number' ? minScore : 45;
    return scoreVideo(video).score >= min;
  }

  const api = {
    KEYWORDS,
    DISCLOSURE_PHRASES,
    SUMMARY_PHRASES,
    STRONG_TERMS,
    TOOL_TERMS,
    WEAK_TERMS,
    textHits,
    disclosureInText,
    looksLikeAI,
    scoreVideo,
    looksLikeAIScored
  };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  if (g) g.UNAIKeywords = api;
})(typeof self !== 'undefined' ? self : typeof window !== 'undefined' ? window : null);
